INSERT INTO fitment_pages (vehicle_id, category_id, title, meta_desc, intro_md, gotchas_md, faq, verdict_md, status, verified_at)
SELECT v.id, c.id, $t$Best Tonneau Covers for 2021–2025 Ford F-150 (5.5 / 6.5 / 8 ft Bed)$t$, $m$Fit-checked tonneau covers for the 14th-gen F-150 sorted by bed length, with the utility-track and Lightning gotchas most listings skip.$m$, $i$Every cover below is matched to a specific F-150 bed. Measure inside the bed from bulkhead to tailgate: 66 in = 5.5 ft, 78 in = 6.5 ft, 96 in = 8 ft. Soft roll-ups are the cheapest, hard tri-folds are the sweet spot, retractables cost the most but seal best.$i$, $g$- **Bed utility track** (optional on XLT and up) blocks most clamp-on side rails — buy a cover that states utility-track compatibility or remove the track (4 bolts per side).
- **Lightning (2022+)** shares the 5.5 ft bed; most 5.5 ft covers fit, but confirm the listing names Lightning because the tailgate is different.
- **Tailgate work surface / step** does not affect cover fit. **Tailgate applique** on Lariat+ can — measure before buying a low-profile hard cover.
- **Bed-side steps** and **BoxLink cleats** must be removed or relocated for full-length rail covers.$g$, $f$[{"q": "Do 5.5 ft F-150 covers fit the F-150 Lightning?", "a": "Most do — the bed is identical. Confirm the listing lists 2022+ Lightning; a few hard covers foul the Lightning tailgate handle."}, {"q": "Will a tonneau fit with the bed utility track?", "a": "Only covers that state utility-track compatibility. Others need the track removed, which is four bolts per side and reversible."}, {"q": "Hard vs soft cover for an F-150 that works?", "a": "Hard tri-fold: 400 lb distributed capacity, lockable with the tailgate. Soft roll-up if you haul tall loads weekly and want full bed access in 10 seconds."}, {"q": "Can I keep my bed-side steps?", "a": "Retractable side steps under the bed are fine; step pads that bolt on the bed rail conflict with rail-mounted covers."}]$f$::jsonb, $v$**Budget:** soft roll-up. **Best overall:** aluminum hard tri-fold. **Premium:** low-profile retractable with a canister — check it clears the utility track.$v$, 'draft', CURRENT_DATE
FROM vehicles v JOIN makes m ON m.id=v.make_id JOIN categories c ON c.slug='tonneau-covers'
WHERE m.slug='ford' AND v.model_slug='f-150' AND v.gen_slug='2021-present'
ON CONFLICT (vehicle_id, category_id) DO UPDATE SET title=EXCLUDED.title, meta_desc=EXCLUDED.meta_desc, intro_md=EXCLUDED.intro_md,
  gotchas_md=EXCLUDED.gotchas_md, faq=EXCLUDED.faq, verdict_md=EXCLUDED.verdict_md, verified_at=EXCLUDED.verified_at, updated_at=now();

